# Compare 8-mask symmetry transformations for demo 1, and 2-mask for demo 2

def coords(rows, color): return {(r,c) for r,row in enumerate(rows) for c,v in enumerate(row) if v==color}
def transform(S,h,w,k,flip=False):
    out=set()
    for r,c in S:
        if flip: c=w-1-c
        for _ in range(k): r,c=c,h-1-r; h,w=w,h
        out.add((r,c))
    return out
# manually encoded local mask coordinates
A8={(2,5),(3,3),(3,4),(3,5),(3,7),(4,3),(5,3),(5,4),(5,5),(5,6),(6,2),(6,6)}
B8={(2,5),(3,2),(3,3),(4,2),(4,4),(4,6),(5,2),(5,4),(6,2),(6,3),(6,4),(7,2)}
# need transform outputs dimensions; check overlap
for f in (False,True):
 for k in range(4):
  T=transform(A8,9,10,k,f)
  print('D1',f,k,len(T),len(T&B8),sorted(T^B8)[:2])
# demo 2 masks local 9x9
A2={(2,4),(3,4),(4,2),(4,3),(4,4),(5,4),(6,4),(6,5),(6,6)}
B2={(2,4),(3,4),(4,2),(4,3),(4,4),(4,5),(4,6),(5,6),(6,6)}
for f in (False,True):
 for k in range(4):
  T=transform(A2,9,9,k,f)
  print('D2',f,k,len(T&B2))
